  "sim.cattle-dairy.desc": "목장과 낙농 단위를 함께 운영하며 방목 관리, 번식, 우유 생산의 균형을 맞추세요.",
  "sim.sheep-farm.title": "양 농장",
  "sim.sheep-farm.desc": "계절 주기로 양 농장을 운영하세요: 새끼 낳기, 양털 깎기, 시장 판매.",
  "sim.network-noc.title": "네트워크 NOC",
  "sim.network-noc.desc": "네트워크 운영 센터 엔지니어처럼 행동하세요 — 압박 속에서 실시간 인프라 장애를 진단하고 해결하세요.",
  "sim.mobile-repair.title": "모바일 수리 워크숍",
  "sim.mobile-repair.desc": "스마트폰을 진단하고 수리하세요 — 디스플레이 교체, 배터리 문제, 메인보드 고장.",
  "sim.laptop-repair.title": "노트북 수리 워크숍",
  "sim.laptop-repair.desc": "노트북 문제를 진단하고 수리하세요: 하드웨어 결함, BIOS 문제, 부품 교체.",
  "sim.perfume-lab.title": "퍼퓸 랩",
  "sim.perfume-lab.desc": "필수 오일과 아로마 컴파운드를 블렌딩해 시그니처 향을 만들고 품질 기준을 달성하세요.",
  "sim.detergent-lab.title": "세제 연구소",
  "sim.detergent-lab.desc": "세정 제품을 배합하세요 — 계면활성제, 필러, 성능 테스트를 예산 안에서 균형 있게 맞추세요.",
  "sim.skin-care-lab.title": "스킨케어 연구소",
  "sim.skin-care-lab.desc": "화장품 포뮬러를 개발하고 테스트하세요. 안전 기준과 효과 목표를 충족하세요.",
  "sim.woodworking.title": "목공 워크숍",
  "sim.woodworking.desc": "맞춤 목공 작업장을 운영하세요: 작업을 계획하고 자재를 관리하며, 가구를 정해진 시간과 예산 내에 완성하세요.",
  "sim.aluminum-glazing.title": "알루미늄 & 글레이징",
  "sim.aluminum-glazing.desc": "견적부터 현장 완료까지 알루미늄 제작 및 유리 시공 사업을 관리하세요.",
  "sim.global-kitchen.title": "글로벌 키친",
  "sim.global-kitchen.desc": "레스토랑 주방을 이끄세요: 메뉴, 직원, 비용, 서비스 교대 전반의 고객 만족도를 관리하세요.",
  "sim.chocolate-factory.title": "초콜릿 공장",
  "sim.chocolate-factory.desc": "제과 공장을 운영하세요 — 카카오 소싱, 생산 일정 관리, 품질 관리.",
  "sim.solar-energy.title": "태양광 에너지 플랜트",
  "sim.solar-energy.desc": "태양광 설치를 설계하고 운영하세요 — 패널 용량 산정, 전력망 수출 관리, 투자수익률(ROI) 추적.",
  "sim.hvac-systems.title": "HVAC 시스템",
  "sim.hvac-systems.desc": "상업용 건물에 난방, 환기, 공조(냉방) 시스템을 설치하고 유지보수하세요.",
  "sim.logistics-supply.title": "물류 & 공급망",
  "sim.logistics-supply.desc": "창고 운영, 차량 경로, 공급업체 관계를 최적화해 배송 KPI를 달성하세요.",
  "sim.barber-salon.title": "바버 샵",
  "sim.barber-salon.desc": "이발소를 운영하세요: 예약, 직원 스케줄, 가격, 고객 유지 전략을 관리합니다.",
  "sim.board-surgeon.title": "보드 서전",
  "sim.board-surgeon.desc": "시뮬레이션 수술실에서 고위험 수술 결정을 내리세요 — 시간 관리와 환자 안전.",
  "sim.english-journey.title": "영어 여정",
  "sim.english-journey.desc": "학습자를 체계적인 영어 프로그램으로 안내하세요. 다양한 수준의 역량에 맞춰 조정합니다.",
  "sim.music-training.title": "음악 트레이닝 스튜디오",
  "sim.music-training.desc": "음악 학교를 운영하세요: 수업을 일정대로 편성하고 악기를 관리하며, 학생이 리사이틀까지 발전하는 과정을 추적하세요.",
  "sim.trade-tycoon.title": "트레이드 타이쿤",
  "sim.trade-tycoon.desc": "거래 제국을 구축하세요 — 싸게 사서 비싸게 팔고, 여러 시장에서 재고와 현금 흐름을 관리하세요.",
  "sim.vehicle-diagnostics.title": "차량 진단 & 수리 시뮬레이터",
  "sim.vehicle-diagnostics.desc": "OBD-II 고장 코드를 진단하고 전기적 결함을 추적하며, 실제 상황의 자동차 수리 워크플로우를 관리하세요.",
  "sim.marine-vessel.title": "선박 추적 & 해상 물류",
  "sim.marine-vessel.desc": "글로벌 선단을 지휘하세요 — 선박을 추적하고, 항만 혼잡, 기상 비상, 운하 지연을 항해로 대응하세요.",
