  "card99.howTo.2": "특수 카드: 킹=0, 퀸=유지, 잭=−10, 에이스=1 또는 11",
  "card99.howTo.3": "합계가 99를 초과하면 목숨을 잃습니다",
  "card99.howTo.4": "마지막까지 살아남은 플레이어가 승리합니다!",
  "dominoes.howTo.1": "도미노 체인의 양 끝에 있는 숫자를 맞추세요",
  "dominoes.howTo.2": "열려 있는 끝과 일치하는 타일을 손에서 내세요",
  "dominoes.howTo.3": "낼 수 없으면 더미에서 뽑으세요",
  "dominoes.howTo.4": "가장 먼저 손을 비우는 사람(또는 눈금 합이 가장 적은 사람)이 승리합니다!",
  "farkle.howTo.1": "주사위 6개를 굴리고 득점되는 주사위를 따로 놓으세요",
  "farkle.howTo.2": "1은 100점 · 5는 50점 · 같은 숫자 3개 = 해당 면 × 100",
  "farkle.howTo.3": "굴린 주사위에서 NO(아무것도) 득점이 나오면, 그건 FARKLE입니다 — 턴을 잃어요!",
  "farkle.howTo.4": "점수를 모아두어 안전하게 가져가거나, 더 많은 위험/보상을 위해 다시 굴리세요",
  "quiz.howTo.1": "객관식 문제 20개를 가능한 한 빨리 푸세요",
  "quiz.howTo.2": "각 문제는 3초 — 빨리 답하세요!",
  "quiz.howTo.3": "정답을 더 빨리 맞히면 더 많은 보너스 점수를 받습니다",
  "quiz.howTo.4": "모든 문제를 풀면 최종 순위를 확인할 수 있어요",
  "memory.howTo.1": "카드 2장을 동시에 뒤집어 짝이 맞는 쌍을 찾으세요",
  "memory.howTo.2": "맞으면 그대로 뒤집힌 상태를 유지합니다",
  "memory.howTo.3": "아니면 둘 다 다시 뒤집혀서 앞면이 보이지 않아요 — 위치를 기억하세요!",
  "memory.howTo.4": "최소한의 이동으로 모든 짝을 맞춰 높은 점수를 노리세요",
  "word.howTo.1": "뒤섞인 글자를 풀어 숨겨진 단어를 만드세요",
  "word.howTo.2": "정확한 순서대로 글자를 눌러 답을 완성하세요",
  "word.howTo.3": "막히면 힌트 버튼을 사용하세요(점수 소모)",
  "word.howTo.4": "8개의 단어를 완성하면 퍼즐이 끝납니다",
  "hangman.howTo.1": "숨겨진 단어를 한 글자씩 추측하세요",
  "hangman.howTo.2": "정답 글자 = 단어에 공개됩니다",
